; beam_000.asm -- chapter 1: a white stripe in the border, 0 T later
; generated by gen01.py
        INCLUDE "msx.inc"
        OUTPUT "beam_000.rom"
        ORG $4000
        CART_HEADER init

IM2_TABLE EQU $C100             ; 257 bytes of $C2: the interrupt vector is $C2C2
IM2_JUMP  EQU $C2C2
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while we set up
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06
        VDP_REG 3, $80
        VDP_REG 4, $00
        VDP_REG 5, $36
        VDP_REG 6, $07
        VDP_REG 7, $01          ; border black
        VRAM_WRITE $2000        ; colour table: black on black
        ld b, 32
        ld a, $11
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, IM2_TABLE        ; the IM 2 table
        ld (hl), $C2
        ld de, IM2_TABLE + 1
        ld bc, 256
        ldir
        ld a, $C3               ; JP handler, at $C2C2
        ld (IM2_JUMP), a
        ld hl, handler
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a
        im 2
        ld c, VDP_CTRL          ; kept for the handler
        ld b, $0F               ; white
        ld d, $01               ; black
        ld e, $87               ; register 7
        ld hl, RAM_START
        VDP_REG 1, $E0          ; display on, frame interrupt on
        ei
main:   halt
        jr main
handler:
        in a, (VDP_CTRL)        ; reading the status acknowledges the interrupt
