        out (c), d              ; value: black
black:  out (c), e              ; R#7 <- black
        ld a,(hl)               ; keeps the stripes still: asmparts.steady
        ld a,(hl)               ; keeps the stripes still: asmparts.steady
        ld a,(hl)               ; keeps the stripes still: asmparts.steady
